void swr_draw_fps(struct swr_output *swr, int size, uint32_t color, int x, int y) {
	struct timespec ts;
	clock_gettime(CLOCK_MONOTONIC, &ts);
	long long now = ((long long)ts.tv_sec * 1000000000LL) + ts.tv_nsec;
	long long diff = now - swr->last_draw_fps_call_time_ns;
	if (swr->last_draw_fps_call_time_ns == 0) {
		diff = 0;
	}
	swr->last_draw_fps_call_time_ns = now;
	float diff_seconds = (float)diff / 1000000000.0F;

	swr->frame_time_history[swr->frame_time_history_index] = diff_seconds;

	swr->history_min = FLT_MAX;
	swr->history_max = 0.0F;
	for (int i = 0; i < SWR_FRAME_TIME_HISTORY_SIZE; i++) {
		if (swr->frame_time_history[i] != 0.0F) {
			swr->history_min = SWR_MIN(swr->history_min, swr->frame_time_history[i]);
			swr->history_max = SWR_MAX(swr->history_max, swr->frame_time_history[i]);
		}
	}

	// Smoothly scale up swr->graph_scale when the peak reduces
	if (swr->history_max > swr->graph_scale) {
		swr->graph_scale = swr->history_max;
	} else {
		float settle_speed = 500.0F;
		float peak_diff = (float)fabs(swr->history_max - swr->graph_scale); // Large peaks will settle faster
		swr->graph_scale = swr__lerp(swr->graph_scale, swr->history_max, SWR_MIN(1.0F, settle_speed * peak_diff * diff_seconds));
	}

	// Draw graph of frame history
	{
		int x_offset = swr->width - SWR_FRAME_TIME_HISTORY_SIZE;
		int y_offset = 0;
		int height = SWR_MIN(swr->height, 100);

		// Draw background
		struct swr_rect background_rect = {
			.x = x_offset,
			.y = y_offset,
			.w = SWR_FRAME_TIME_HISTORY_SIZE,
			.h = height,
		};
		swr_draw_rectangle(swr, background_rect, swr_rgba(0,0,0,200));

		// Draw lines in the graph
		for (int i = 1; i < 1 + SWR_FRAME_TIME_HISTORY_SIZE; i++) {
			int index = i - 1;
			float time = swr->frame_time_history[index];

			int time_height = (int)(time / swr->graph_scale * (float)height);
			struct swr_rect rect = {
				.x = x_offset + i - 1,
				.y = y_offset + (height - time_height),
				.w = 1,
				.h = SWR_MAX(1, time_height),
			};

			uint8_t alpha = 140;
			if (index > swr->frame_time_history_index) {
				alpha = 30;
			}

			uint32_t rect_color = swr_rgba(255, 255, 255, alpha);
			swr_draw_rectangle(swr, rect, rect_color);
		}

		{
			// Draw max line
			uint32_t max_line_color = 0xFFF75959;
			int peak_height = (int)(swr->history_max / swr->graph_scale * (float)height);
			int peak_y = y_offset + (height - peak_height);
			struct swr_rect rect = {
				.x = x_offset,
				.y = peak_y,
				.w = SWR_FRAME_TIME_HISTORY_SIZE,
				.h = 1,
			};
			swr_draw_rectangle(swr, rect, max_line_color);

			// Draw max time in milliseconds
			int text_y = peak_y;
			char s[32];
			snprintf(s, 32, "%.2fms", swr->history_max * 1000.0F);
			struct swr_rect measured = swr_measure_text(swr, s, size, swr_rgb(255,255,255), 0, text_y);
			swr_draw_text(swr, s, size, max_line_color, x_offset - measured.w - 5, text_y);
		}

		{
			// Draw min line
			//uint32_t min_line_color = 0xFF59A3F7;
			uint32_t min_line_color = 0xFF166AC9;
			int peak_height = (int)(swr->history_min / swr->graph_scale * (float)height);
			int peak_y = y_offset + (height - peak_height);
			struct swr_rect rect = {
				.x = x_offset,
				.y = peak_y,
				.w = SWR_FRAME_TIME_HISTORY_SIZE,
				.h = 1,
			};
			swr_draw_rectangle(swr, rect, min_line_color);

			// Draw min time in milliseconds
			int text_y = peak_y;
			char s[32];
			snprintf(s, 32, "%.2fms", swr->history_min * 1000.0F);
			struct swr_rect measured = swr_measure_text(swr, s, size, swr_rgb(255,255,255), 0, text_y);
			swr_draw_text(swr, s, size, min_line_color, x_offset - measured.w - 5, text_y);
		}
	}
	swr->frame_time_history_index = (swr->frame_time_history_index + 1) % SWR_FRAME_TIME_HISTORY_SIZE;

	float fps = 1.0F / diff_seconds;
	char fpsText[32];
	snprintf(fpsText, 32, "%.1f fps", fps);
	swr_draw_text(swr, fpsText, size, color, x, y);
}

struct swr_rect swr_draw_text(struct swr_output *swr, const char *text, int32_t size, uint32_t color, int x, int y) {
	swr__crash_if_null(swr);

	if (size != swr->last_default_font_size) {
		int err = swr_fontbmp_generate_from_memory(&swr->default_font, swr_default_font_data, swr_default_font_data_size, size);
		if (err) {
			printf("swr_draw_text: A call to swr_fontbmp_generate_from_memory errored with code %i\n", err);
			assert(0);
		}

		swr->last_default_font_size = size;
	}

	return swr_draw_text_ex(swr, text, &swr->default_font, color, x, y);
}

