// Returns the intersection of two rectangles.
// If there is no intersection, it returns an empty rectangle with x=0, y=0, w=0, h=0
struct swr_rect swr_rect_intersect(struct swr_rect a, struct swr_rect b) {
	int32_t x1 = SWR_MAX(a.x, b.x);
	int32_t x2 = SWR_MIN(a.x + a.w, b.x + b.w);
	int32_t y1 = SWR_MAX(a.y, b.y);
	int32_t y2 = SWR_MIN(a.y + a.h, b.y + b.h);

	struct swr_rect out;
	if (x2 >= x1 && y2 >= y1) {
		out = (struct swr_rect){.x = x1, .y = y1, .w = x2-x1, .h = y2-y1};
	} else {
		out = (struct swr_rect){.x = 0, .y = 0, .w = 0, .h = 0};
	}

	return out;
}

int swr_is_point_in_rect(struct swr_rect rect, int x, int y) {
	if (rect.w == 0 && rect.h == 0) {
		return 0;
	}

	int is_x_within = x >= rect.x && x <= (rect.x + rect.w);
	int is_y_within = y >= rect.y && y <= (rect.y + rect.h);
	return is_x_within && is_y_within;
}

struct swr_font swr_fontbmp_initialize() {
#ifdef USE_DURING_DEVELOPMENT
	printf("\x1b[31mRemember to remove USE_DURING_DEVELOPMENT !\x1b[0m\n");
#endif
	struct swr_font out;
	out.glyph_list = malloc(sizeof(struct swr_glyph_bitmap) * 256);
	out.internal_bitmap_data = NULL;
	return out;
}

void swr_fontbmp_deinitialize(struct swr_font font) {
	free(font.glyph_list);
	free(font.internal_bitmap_data);
}

// Frees the font.bitmap_data before re-allocating it.
// Returns non-zero on failure
FT_Error swr_fontbmp_generate(struct swr_font *font, const char *font_filename, const int32_t font_height_pixels) {
	assert(font != NULL);

	int fd = open(font_filename, O_RDONLY);
	if (fd == -1) {
		printf("swr_fontbmp_generate: Failed to open font file: %s\n", font_filename);
		return 1;
	}

	struct stat st;
	if (fstat(fd, &st) == -1) {
		printf("swr_fontbmp_generate: Failed to stat font file: %s\n", font_filename);
		close(fd);
		return 1;
	}

	size_t font_data_size = (size_t)st.st_size;
	unsigned char *font_data = mmap(NULL, font_data_size, PROT_READ, MAP_SHARED, fd, 0);
	FT_Error err = swr_fontbmp_generate_from_memory(font, font_data, font_data_size, font_height_pixels);

	close(fd);
	munmap(font_data, font_data_size);
	return err;
}

// Frees the font.bitmap_data before re-allocating it.
// Returns non-zero on failure
FT_Error swr_fontbmp_generate_from_memory(struct swr_font *font, const unsigned char *font_data, size_t font_data_size, const int32_t font_height_pixels) {
	assert(font != NULL);

#ifdef SWR_DEBUG_INFO
	struct timespec time;
	clock_gettime(CLOCK_MONOTONIC, &time);
	double start = (double)time.tv_sec * 1000.0 + (double)time.tv_nsec / 1000000.0; // Milliseconds
#endif

	FT_Library library;
	FT_Error error = 0;
	FT_Face face = NULL;

	/* Initialize freetype2 */
	error = FT_Init_FreeType(&library);
	if (error) {
		goto done;
	}

	error = FT_New_Memory_Face(library, font_data, (FT_Long)font_data_size, 0, &face);
	if (error) {
		goto done;
	}

	error = FT_Set_Pixel_Sizes(face, 0, (FT_UInt)font_height_pixels);
	if (error) {
		goto done;
	}

	/* Figure out how big the resulting bitmap data will be */
	unsigned int bitmap_size = 0;
	for (int character = 0; character <= 255; character++) {
		if (character == ' ' || character == '\t' || character == '\n') {
			continue;
		}

		error = FT_Load_Char(face, (FT_ULong)character, FT_LOAD_RENDER); // FT_LOAD_RENDER calls FT_Render_Glyph for us.
		if (error) {
			goto done;
		}

		unsigned int width = face->glyph->bitmap.width;
		unsigned int pitch = (unsigned int)face->glyph->bitmap.pitch;
		unsigned int rows = face->glyph->bitmap.rows;
		assert(pitch == width);
		if (!face->glyph->bitmap.buffer) {
			continue;
		}

		bitmap_size += pitch * rows;
	}

	/* Generate the font atlas */
	free(font->internal_bitmap_data);
	font->internal_bitmap_data = malloc(bitmap_size);
	memset(font->internal_bitmap_data, 0, bitmap_size);

	// Linear -> SRGB lookup table
	uint8_t linear_to_srgb_lut[256];
	for (int i = 0; i < 256; i++) {
		linear_to_srgb_lut[i] = (uint8_t)(255.0F * pow((float)i / 255.0F, 1.0 / 1.5));
	}

	unsigned int index = 0;
	for (int character = 0; character <= 255; character++) {
		font->glyph_list[character] = (struct swr_glyph_bitmap){.width = 0, .rows = 0, .bitmap_data = NULL};

		if (character == ' ') {
			error = FT_Load_Char(face, ' ', FT_LOAD_DEFAULT);
			font->glyph_list[character] = (struct swr_glyph_bitmap){
				.advance_x = face->glyph->advance.x,
				.advance_y = face->glyph->advance.y,
				.bitmap_data = NULL,
			};
			continue;
		} else if (character == '\t') {
			error = FT_Load_Char(face, ' ', FT_LOAD_DEFAULT);
			font->glyph_list[character] = (struct swr_glyph_bitmap){
				.advance_x = face->glyph->advance.x * 4, // 4 spaces
				.advance_y = 0,
				.bitmap_data = NULL,
			};
			continue;
		} else if (character == '\n') {
			error = FT_Load_Char(face, ' ', FT_LOAD_DEFAULT);
			font->glyph_list[character] = (struct swr_glyph_bitmap){
				.advance_x = 0, // It's up to the renderer to reset x position.
				.advance_y = face->size->metrics.height,
				.bitmap_data = NULL,
			};
			continue;
		}

		error = FT_Load_Char(face, (FT_ULong)character, FT_LOAD_RENDER); // FT_LOAD_RENDER calls FT_Render_Glyph for us.
		if (error) {
			goto done;
		}

		if (!face->glyph->bitmap.buffer) {
			continue;
		}

		assert(face->glyph->bitmap.num_grays == 256);
		assert(face->glyph->bitmap.pixel_mode == 2);
		assert(face->glyph->bitmap.palette_mode == 0);
		assert(face->glyph->bitmap.palette == 0);
		assert((unsigned int)face->glyph->bitmap.pitch == face->glyph->bitmap.width);

		unsigned int width = face->glyph->bitmap.width;
		unsigned int pitch = (unsigned int)face->glyph->bitmap.pitch;
		unsigned int rows = face->glyph->bitmap.rows;

		assert(width == pitch);

		memcpy(&font->internal_bitmap_data[index], face->glyph->bitmap.buffer, pitch*rows);
		// Convert linear to srgb
		for (unsigned i = 0; i < pitch*rows; i++) {
			font->internal_bitmap_data[index + i] = linear_to_srgb_lut[font->internal_bitmap_data[index + i]];
		}

		font->glyph_list[character] = (struct swr_glyph_bitmap){
			.width = width,
			.rows = rows,
			.pitch = pitch,
			.bitmap_data = &(font->internal_bitmap_data[index]),
			.advance_x = face->glyph->advance.x,
			.advance_y = face->glyph->advance.y,
			.bitmap_left = face->glyph->bitmap_left,
			.bitmap_top = face->glyph->bitmap_top,
		};
		index += pitch * rows;
		assert(index <= bitmap_size);
	}

	assert(error == 0);
	font->ascender = face->size->metrics.ascender;

	//printf("actual size: %i, should be: %i\n", index, bitmap_size);
	assert(index == bitmap_size);
done:
	FT_Done_Face(face);
	FT_Done_FreeType(library);

#ifdef SWR_DEBUG_INFO
	clock_gettime(CLOCK_MONOTONIC, &time);
	double end = (double)time.tv_sec * 1000.0 + (double)time.tv_nsec / 1000000.0; // Milliseconds
	double duration = end - start;
	printf("swr: swr_fontbmp_generate_from_memory took %f ms\n", duration);
#endif

	return error;
}

/* PRIVATE FUNCTIONS IMPLEMENTATIONS */
void swr__crash_if_null(struct swr_output *swr) {
	if (swr == NULL) {
		fprintf(stderr, "swr: swr_output was NULL\n");
		assert(0);
	}

	if (swr->dest == NULL) {
		fprintf(stderr, "swr: dest was NULL, did you forget to call swr_set_output() ?\n");
		assert(0);
	}
}

// Draws a single-channel 8-bit alpha image to dest, outputs in ARGB
// Returns non-zero if it would draw outside of the screen (nothing to draw)
int swr__draw_glyph(struct swr_output *swr, struct swr_glyph_bitmap img, uint32_t color, int img_x, int img_y) {
	struct swr_rect buffer_rect = {.x = 0,     .y = 0,     .w = (int)swr->width, .h = (int)swr->height};
	struct swr_rect img_rect =    {.x = img_x, .y = img_y, .w = (int)img.width,  .h = (int)img.rows};

	struct swr_rect visible = swr_rect_intersect(buffer_rect, img_rect);
	int x_offset = -SWR_MIN(0, img_x);
	int y_offset = -SWR_MIN(0, img_y);

	// Nothing to draw
	if (visible.w == 0 && visible.h == 0) {
		return 1;
	}

	color &= 0x00FFFFFF;
	for (int y = 0; y < visible.h; y++) {
		for (int x = 0; x < visible.w; x++) {
			int img_sample_x = x + x_offset;
			int img_sample_y = y + y_offset;
			assert(img.pitch == img.width);

			// Fetch the pixel from img
			int img_index = img_sample_y * (int)img.pitch + img_sample_x;
			uint8_t alpha = img.bitmap_data[img_index];

			int buffer_index = (visible.y+y) * swr->width + (visible.x+x);
			uint32_t img_color = (uint32_t)(swr_alpha_blend(swr->dest[buffer_index], (uint32_t)alpha << 24 | color));

			// Set the pixel
			swr->dest[buffer_index] = img_color;
		}
	}

	return 0;
}

// Returns text width and height, along with xy offset from the original x,y inputs.
struct swr_rect swr__draw_text_impl(struct swr_output *swr, const char *text, struct swr_font *font, uint32_t color, int x, int y, int actually_draw) {
	swr__crash_if_null(swr);

	int pen_x = x;
	int pen_y = y + (int)(font->ascender >> 6);

	struct swr_rect bounding_box = {
		.x = 2147483647,
		.y = 2147483647,
		.w = 0,
		.h = 0,
	};

	for (size_t i = 0; i < strlen(text); i++) {
		unsigned char c = *(unsigned char*)&text[i]; // Need to reinterpret signed char as unsigned.

		struct swr_glyph_bitmap glyph = font->glyph_list[c];
		if (glyph.bitmap_data == NULL) {
			pen_x += (int)(glyph.advance_x >> 6);
			pen_y += (int)(glyph.advance_y >> 6);

			if (c == '\n') {
				pen_x = x;
			}

			// TODO: Add bounding_box growth here aswell
			continue;
		}

		int x_pos = pen_x + glyph.bitmap_left;
		int y_pos = pen_y - glyph.bitmap_top;

		if (actually_draw) {
			if (swr__draw_glyph(swr, glyph, color, x_pos, y_pos)) {
				// Nothing to draw beyond this line.
				// FIXME: Skip to the next line. Also return if we drew the last visible line.
				continue;
			}
		}

		// Bounding box growth
		int min_x = x_pos;
		int min_y = y_pos;
		int max_x = x_pos + (int)glyph.width;
		int max_y = y_pos + (int)glyph.rows;
		if (min_x < bounding_box.x) bounding_box.x = min_x;
		if (min_y < bounding_box.y) bounding_box.y = min_y;
		if (max_x > bounding_box.w) bounding_box.w = max_x;
		if (max_y > bounding_box.h) bounding_box.h = max_y;

		pen_x += (int)(glyph.advance_x >> 6);
		pen_y += (int)(glyph.advance_y >> 6);
	}

	bounding_box.w -= bounding_box.x;
	bounding_box.h -= bounding_box.y;
	bounding_box.x -= x;
	bounding_box.y -= y;
	return bounding_box;
}

float swr__sdf_rect(float x, float y, struct swr_float_rect rect, float radius) {
	rect.w -= 1.0F;
	rect.h -= 1.0F;

	// Fast path for the inner horizontal rectangle
	if (y > rect.y + radius && y < rect.y + rect.h - radius) {
		return 1.0F;
	}

	// Fast path for the inner vertical rectangle
	if (x > rect.x + radius && x < rect.x + rect.w - radius) {
		return 1.0F;
	}

	x -= rect.x + rect.w / 2.0F;
	y -= rect.y + rect.h / 2.0F;

	float q_x = (float)fabs(x) - rect.w / 2.0F + radius;
	float q_y = (float)fabs(y) - rect.h / 2.0F + radius;
	float q_x_positive = SWR_MAX(0.0F, q_x);
	float q_y_positive = SWR_MAX(0.0F, q_y);

	float result = SWR_MIN(0.0F, SWR_MAX(q_x, q_y)) + (float)sqrt(q_x_positive*q_x_positive + q_y_positive*q_y_positive) - radius;
	return 1.0F - SWR_MAX(0.0F, SWR_MIN(1.0F, result));
}

float swr__sdf_rect_outline(float x, float y, struct swr_float_rect rect, float radius, float thickness_inward, float thickness_outward) {
	rect.w -= 1.0F;
	rect.h -= 1.0F;

	x -= rect.x + rect.w / 2.0F;
	y -= rect.y + rect.h / 2.0F;

	float q_x = (float)fabs(x) - rect.w / 2.0F + radius;
	float q_y = (float)fabs(y) - rect.h / 2.0F + radius;
	float q_x_positive = SWR_MAX(0.0F, q_x);
	float q_y_positive = SWR_MAX(0.0F, q_y);

	float result = SWR_MIN(0.0F, SWR_MAX(q_x, q_y)) + (float)sqrt(q_x_positive*q_x_positive + q_y_positive*q_y_positive) - radius;

	float t_in = thickness_inward / 2.0F;
	float t_out = thickness_outward / 2.0F;
	result = SWR_MAX(0.0F, (float)fabs(result - t_out + t_in) - t_out - t_in);
	return 1.0F - SWR_MAX(0.0F, SWR_MIN(1.0F, result));
}

// At t = 0.0, a is returned. At t = 1.0, b is returned.
float swr__lerp(float a, float b, float t) {
	return a * (1.0F - t) + b*t;
}

void swr__print_128i(__m128i value) {
	uint8_t bytes[16];
	_mm_storeu_si128((__m128i *)bytes, value);

	for (int i = 15; i >= 0; i--) {
		printf("%02x", bytes[i]);
	}
	printf("\n");
}

void swr__print_256i(__m256i value) {
	uint8_t bytes[32];
	_mm256_storeu_si256((__m256i *)bytes, value);

	for (int i = 31; i >= 0; i--) {
		printf("%02x", bytes[i]);
	}
	printf("\n");
}
